import{_ as t,o as a,c as r,a4 as d}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"Actions liées des ADR — recensement et triage","description":"Extrait de docs/adr/actions-ouvertes.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"Actions liées des ADR — recensement et triage","description":"Extrait de docs/adr/actions-ouvertes.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/actions-ouvertes.md","filePath":"developpeurs/adr/actions-ouvertes.md"}'),s={name:"developpeurs/adr/actions-ouvertes.md"};function o(n,e,i,l,c,u){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="actions-liées-des-adr--recensement-et-triage" tabindex="-1">Actions liées des ADR — recensement et triage <a class="header-anchor" href="#actions-liées-des-adr--recensement-et-triage" aria-label="Permalink to &quot;Actions liées des ADR — recensement et triage {#actions-liées-des-adr--recensement-et-triage}&quot;">​</a></h1><h2 id="état-actuel" tabindex="-1">État actuel <a class="header-anchor" href="#état-actuel" aria-label="Permalink to &quot;État actuel {#état-actuel}&quot;">​</a></h2><p><strong>Au 05/11/2026 : 58 cases ouvertes, 212 cochées, aucune bloquante</strong>, sur les ADR-0001 à 0076.</p><p>Pour rejouer le décompte, sur les ADR elles-mêmes (le recensement ci-dessous est en tableaux, sans case) :</p><ul><li>ouvertes : <code>cat docs/adr/00*.md | grep -o &quot;\\- \\[ \\]&quot; | wc -l</code> ;</li><li>cochées : <code>cat docs/adr/00*.md | grep -o &quot;\\- \\[x\\]&quot; | wc -l</code>.</li></ul><p><strong>Périmètre :</strong> les cases non cochées des ADR de <code>docs/adr/</code>. Les cases conditionnelles sont comptées parmi les ouvertes ; une ligne de tableau peut regrouper deux cases (ADR-0071 et 0072).</p><p><strong>Pourquoi ce document.</strong> Plusieurs actions restées ouvertes avaient en réalité été closes par une ADR ou un commit ultérieurs, sans jamais être rétro-cochées. La somme des cases ouvertes ne valait donc pas état du reste à faire, ce qui est pourtant sa seule fonction. La revue a d&#39;abord été faite sur le corpus documentaire. Les verdicts « à confirmer » ont ensuite été vérifiés dans le code. Les cases closes ont été cochées dans les ADR elles-mêmes, chacune avec sa preuve.</p><p>Les états successifs du recensement, date par date, sont dans la section « Historique », en fin de document.</p><table tabindex="0"><thead><tr><th>Verdict</th><th>Sens</th></tr></thead><tbody><tr><td><strong>Bloquante</strong></td><td>Reste à faire, et une fonction livrée ne marche pas sans elle.</td></tr><tr><td><strong>Ouverte</strong></td><td>Reste à faire.</td></tr><tr><td><strong>Conditionnelle</strong></td><td>Rien à programmer tant que son déclencheur ne survient pas.</td></tr></tbody></table><hr><h2 id="closes-pendant-la-revue--cochées-dans-les-adr-le-18092026" tabindex="-1">Closes pendant la revue — cochées dans les ADR le 18/09/2026 <a class="header-anchor" href="#closes-pendant-la-revue--cochées-dans-les-adr-le-18092026" aria-label="Permalink to &quot;Closes pendant la revue — cochées dans les ADR le 18/09/2026 {#closes-pendant-la-revue--cochées-dans-les-adr-le-18092026}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ADR</th><th>Action</th><th>Preuve</th></tr></thead><tbody><tr><td>0002</td><td>Anticiper un sous-ensemble minimal du Plugin SDK</td><td>Sans objet : E7 livré, cf. ADR-0010.</td></tr><tr><td>0008</td><td>Limitation de débit sur <code>POST /auth/login</code></td><td>ADR-0031 (17/09).</td></tr><tr><td>0009</td><td>Brancher <code>EndUserSubject</code> sur une session usager réelle</td><td>Vérifié dans le code : <code>app/end_users/identity.py</code>.</td></tr><tr><td>0010</td><td>Brancher le Provider Manager dans <code>invoke_ai</code></td><td>Vérifié dans le code : <code>app/plugins/ai.py</code>, <code>current_provider_manager()</code>.</td></tr><tr><td>0010</td><td>Enrichir le plugin SVE : page de relecture, logique conditionnelle</td><td>Vérifié dans le code : état <code>pending_review</code>, <code>app/forms/submissions.py</code>.</td></tr><tr><td>0014</td><td>Brancher un ordonnanceur sur les purges et les envois en attente</td><td>ADR-0027 (14/09).</td></tr><tr><td>0023</td><td>Publication effective sur PyPI</td><td>ADR-0024 : <code>teuthis-cms</code> 0.1.0 publié le 29/08.</td></tr><tr><td>0024</td><td>Confirmer le propriétaire du dépôt ; créer les environnements <code>pypi</code>/<code>testpypi</code> ; essai TestPyPI</td><td>Faits le 29/08. L&#39;ordre exact des deux essais n&#39;a pas été consigné, et l&#39;ADR le dit.</td></tr><tr><td>0029</td><td>Limitation de débit, « laissée hors de ce lot »</td><td>ADR-0031 (17/09).</td></tr><tr><td>0030</td><td>Export RGPD complet d&#39;un compte usager (constat 9.1)</td><td>Commit <code>629fdfa</code> (17/09).</td></tr><tr><td>0030</td><td>Droits d&#39;accès et d&#39;effacement du déposant sans compte (constat 9.2)</td><td>ADR-0032 (17/09).</td></tr><tr><td>0031</td><td>Énumération des logins insensible au temps de réponse</td><td>Commit <code>028291e</code> (18/09).</td></tr><tr><td>0031</td><td>Captcha à l&#39;inscription usager</td><td>Commit <code>028291e</code> (18/09).</td></tr></tbody></table><p><strong>Ce qui n&#39;était pas une contradiction.</strong> La revue documentaire avait relevé une contradiction entre l&#39;ADR-0023 (« publication pas encore prise ») et l&#39;ADR-0024 (« le Core est publié »). Les faits donnent raison à l&#39;ADR-0024 : c&#39;étaient quatre cases jamais cochées, pas un désaccord.</p><h2 id="closes-pendant-laudit-du-26092026--cochées-dans-les-adr" tabindex="-1">Closes pendant l&#39;audit du 26/09/2026 — cochées dans les ADR <a class="header-anchor" href="#closes-pendant-laudit-du-26092026--cochées-dans-les-adr" aria-label="Permalink to &quot;Closes pendant l&#39;audit du 26/09/2026 — cochées dans les ADR {#closes-pendant-laudit-du-26092026--cochées-dans-les-adr}&quot;">​</a></h2><p>Livrées en août, jamais rétro-cochées. Relevées par l&#39;audit du 26/09 (<code>docs/audits/2026-09-26-audit-complet.md</code>, SUIVI-1 à 4).</p><table tabindex="0"><thead><tr><th>ADR</th><th>Action</th><th>Preuve</th></tr></thead><tbody><tr><td>0014</td><td>Brancher une source de pré-remplissage sur <code>register_prefill_source()</code></td><td><code>fa25069</code> (20/08) : <code>app/composition.py</code>, <code>app/end_users/prefill.py</code>.</td></tr><tr><td>0019</td><td>Griser dans la palette un bloc dont la page atteint sa borne <code>max_per_page</code></td><td><code>f178304</code> (21/08) : <code>components/pagebuilder/PageBlockPalette.vue</code>.</td></tr><tr><td>0021</td><td>Arbitrage des conflits de taxonomie</td><td><code>7638d60</code> (28/08) : <code>pages/multisite/conflits.vue</code>.</td></tr><tr><td>0022</td><td>Provisionnement : rapport et blocs retirés</td><td><code>7638d60</code> (28/08) : <code>pages/multisite/sites.vue</code>.</td></tr><tr><td>0016</td><td>Synonymes et mots vides présentés côte à côte</td><td><code>apps/admin/pages/recherche/dictionnaires.vue</code> (sections l. 308 et 488, un seul appel l. 50) : l&#39;un sous l&#39;autre sur le même écran, jugé suffisant par le Product Owner (SUIVI-5, 28/09).</td></tr></tbody></table><h2 id="closes-pendant-le-lot-6-de-laudit-du-2110-04112026--cochées-dans-les-adr" tabindex="-1">Closes pendant le lot 6 de l&#39;audit du 21/10 (04/11/2026) — cochées dans les ADR <a class="header-anchor" href="#closes-pendant-le-lot-6-de-laudit-du-2110-04112026--cochées-dans-les-adr" aria-label="Permalink to &quot;Closes pendant le lot 6 de l&#39;audit du 21/10 (04/11/2026) — cochées dans les ADR {#closes-pendant-le-lot-6-de-laudit-du-2110-04112026--cochées-dans-les-adr}&quot;">​</a></h2><p>Relevées par l&#39;audit du 21/10 (<code>docs/audits/2026-10-21-audit-complet.md</code>, SUIVI-16).</p><table tabindex="0"><thead><tr><th>ADR</th><th>Action</th><th>Preuve</th></tr></thead><tbody><tr><td>0006</td><td>Installer la GitHub App Renovate</td><td>Issue #36 tenue par <code>app/renovate</code>, mise à jour le 04/11/2026 : l&#39;application est installée et produit ses mises à jour.</td></tr></tbody></table><h2 id="contradictions--levées-le-19092026" tabindex="-1">Contradictions — levées le 19/09/2026 <a class="header-anchor" href="#contradictions--levées-le-19092026" aria-label="Permalink to &quot;Contradictions — levées le 19/09/2026 {#contradictions--levées-le-19092026}&quot;">​</a></h2><p>La revue en avait relevé deux ; elles sont tranchées, et leurs cases sont cochées dans les ADR.</p><table tabindex="0"><thead><tr><th>ADR</th><th>Contradiction</th><th>Résolue par</th></tr></thead><tbody><tr><td>0004</td><td>Aucun modèle d&#39;embedding élu, alors que l&#39;Epic E8 est livré.</td><td><a href="/teuthis-cms-distribution/developpeurs/adr/0037-modele-embedding-par-defaut-bge-m3">ADR-0037</a> : <code>ollama/bge-m3</code> proposé par défaut, jamais appelé sans politique.</td></tr><tr><td>0033</td><td>Refuser les cookies interdisait les démarches en ligne, quand le captcha tiers est soumis au consentement.</td><td><a href="/teuthis-cms-distribution/developpeurs/adr/0036-captcha-sans-consentement-repli-altcha">ADR-0036</a> : repli Altcha, sans cookie ni tiers, proposé d&#39;office.</td></tr></tbody></table><h2 id="bloquante--close-le-19092026" tabindex="-1">Bloquante — close le 19/09/2026 <a class="header-anchor" href="#bloquante--close-le-19092026" aria-label="Permalink to &quot;Bloquante — close le 19/09/2026 {#bloquante--close-le-19092026}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ADR</th><th>Action</th><th>Close par</th></tr></thead><tbody><tr><td>0017</td><td>Pièces jointes de candidature par adressage par identifiant</td><td><a href="/teuthis-cms-distribution/developpeurs/adr/0038-pieces-jointes-des-formulaires-publics">ADR-0038</a> : dépôt public sous un porteur d&#39;attente, rattachement vérifié, type réel contrôlé, antivirus ClamAV livré inactif, lecture par un agent depuis le dossier. Vaut pour les quatre formulaires publics qui déclarent un fichier.</td></tr></tbody></table><h2 id="ouvertes--écrans-dadministration-manquants" tabindex="-1">Ouvertes — écrans d&#39;administration manquants <a class="header-anchor" href="#ouvertes--écrans-dadministration-manquants" aria-label="Permalink to &quot;Ouvertes — écrans d&#39;administration manquants {#ouvertes--écrans-dadministration-manquants}&quot;">​</a></h2><p>C&#39;est la réserve à opposer à la formule « l&#39;admin Nuxt couvre les 15 Epics » (ADR-0023) : elle décrit une surface, pas une complétude.</p><table tabindex="0"><thead><tr><th>ADR</th><th>Écran attendu</th></tr></thead><tbody><tr><td>—</td><td>Aucun depuis le 30/09/2026 : l&#39;écran « Apparence » (ADR-0049), les packs de plugins (ADR-0028) et la fraîcheur des traductions (ADR-0025) sont livrés. Restent les recettes dans un navigateur.</td></tr></tbody></table><h2 id="ouvertes--côté-site-public" tabindex="-1">Ouvertes — côté site public <a class="header-anchor" href="#ouvertes--côté-site-public" aria-label="Permalink to &quot;Ouvertes — côté site public {#ouvertes--côté-site-public}&quot;">​</a></h2><p>Le dépôt livre un site de démarrage facultatif (<code>apps/front</code>, ADR-0047 ; notice §1), qui ne fait pas encore tout ce qu&#39;un site public doit faire. L&#39;API sert désormais ce qu&#39;il faut (ADR-0034, ADR-0035) : les actions 0020 et 0025 reviennent à l&#39;intégrateur, ou au front de démarrage pour la part qu&#39;il couvre.</p><table tabindex="0"><thead><tr><th>ADR</th><th>Action</th></tr></thead><tbody><tr><td>0020</td><td>Recette de l&#39;attribution ODbL : crédits de la carte <strong>et</strong> mentions légales. La notice (§7.10) la confie à l&#39;exploitant, pour chaque site ; la case reste ouverte, car c&#39;est une recette par site.</td></tr><tr><td>0047</td><td>Recette réelle : un référent non développeur par profil, sur un serveur jetable, sans aide.</td></tr><tr><td>0059</td><td>Envoi SMS du lien « mes données », quand une passerelle SMS sera retenue.</td></tr></tbody></table><h2 id="ouvertes--sécurité-et-exploitation" tabindex="-1">Ouvertes — sécurité et exploitation <a class="header-anchor" href="#ouvertes--sécurité-et-exploitation" aria-label="Permalink to &quot;Ouvertes — sécurité et exploitation {#ouvertes--sécurité-et-exploitation}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ADR</th><th>Action</th></tr></thead><tbody><tr><td>0015</td><td>Vérifier que le fournisseur de captcha retenu propose une alternative accessible (point de rupture RGAA classique).</td></tr><tr><td>0027</td><td>Éprouver le canal courriel contre un relais réel de collectivité : la recette n&#39;a exercé que Mailpit et des doublures.</td></tr><tr><td>0036</td><td>Réévaluer la difficulté d&#39;Altcha si le repli devient le chemin des robots — aucun journal ne permet encore de le mesurer.</td></tr><tr><td>0038</td><td>Éprouver l&#39;antivirus contre le démon ClamAV réel : la recette n&#39;a exercé qu&#39;un faux démon.</td></tr><tr><td>0039</td><td>Brancher un envoi vers un agrégateur de journaux externe (Loki, ELK, CloudWatch…) : laissé à l&#39;exploitant.</td></tr><tr><td>0039</td><td>Rotation et conservation des journaux du conteneur : à la charge de l&#39;exploitant, comme pour tout journal technique sans durée de conservation déclarée au registre des traitements. La pile <code>deploy/</code> (ADR-0045) pose une rotation de 10 Mo × 5 fichiers par conteneur ; la durée de conservation reste à décider.</td></tr><tr><td>0040</td><td>Éprouver l&#39;échangeur OIDC contre l&#39;intégration FranceConnect réelle : la recette n&#39;a exercé qu&#39;un fournisseur simulé.</td></tr><tr><td>0074</td><td>Traiter les comptes fédérés déjà créés avec une adresse non vérifiée : rien ne dit si leur adresse l&#39;était (<code>email_verified</code> n&#39;a jamais été conservée). Proposition : script d&#39;exploitation unique, en <code>dry_run</code> d&#39;abord, qui vide l&#39;adresse des comptes fédérés des organisations sans fournisseur « de confiance ». À décider, sans migration.</td></tr><tr><td>0074</td><td>Établir ce que FranceConnect rend réellement dans <code>email</code> et <code>email_verified</code> (intégration réelle) avant de recommander ou non « Adresse de confiance » pour ce fournisseur.</td></tr><tr><td>0074</td><td>Instruire le même défaut pour le numéro de téléphone de l&#39;identité pivot : <code>phone_number_verified</code> n&#39;est pas lue par <code>account_phone_keys</code> (alertes SMS rattachées au compte).</td></tr><tr><td>0044</td><td>Éprouver l&#39;antivirus contre le démon ClamAV réel avec une vidéo de plus de 100 Mo : confirmer que l&#39;image lit les variables <code>CLAMD_CONF_*</code> et que le dépassement de ses limites est refusé, jamais accepté.</td></tr><tr><td>0042</td><td>Recette dans un navigateur de la fiche média (proposer, accepter et appliquer une alternative) et du sélecteur de l&#39;entête de liste, après reconstruction de l&#39;image <code>cms-admin</code>. La recette du lot 1 n&#39;a pas non plus été faite dans un navigateur.</td></tr><tr><td>0035</td><td>Redirection au changement de préfixe d&#39;un type ; contrôles réciproques au détachement d&#39;une page et au changement des langues d&#39;un site.</td></tr><tr><td>0053</td><td>Retirer les alias dépréciés des écritures anonymes (<code>/api/v1/cookies/…</code>, votes hors <code>/public/</code>), par une ADR, quand les fronts connus auront migré.</td></tr><tr><td>0063</td><td>Renouveler <code>JETON_DISTRIBUTION</code> avant son échéance.</td></tr><tr><td>0075</td><td>Analyser les images 0.11.3 publiées (la 0.11.2 n&#39;a pas été distribuée) (empreinte de GHCR) et noter que la CVE-2026-85091 a disparu de ce qui est réellement déployé (SUIVI-17).</td></tr><tr><td>0076</td><td>Éprouver la chaîne jusqu&#39;au dépôt de distribution sur la publication réelle de la 0.11.3 (la 0.11.2 s&#39;est arrêtée avant les notes, le site et <code>distribution</code>), puis la vérification de l&#39;archive par une commande <code>teuthis</code> 0.11.3 lors de la mise à jour suivante.</td></tr><tr><td>0056</td><td>Recette contre OpenAI, Anthropic et Gemini, chacun ouvert par un acte délibéré de l&#39;administrateur hors du mode <code>restricted</code>, sur une organisation jetable. Les adaptateurs sont livrés (01/10/2026), mais toutes leurs entrées du catalogue restent à <code>structured_output: none</code> : chaque entrée ne passe à <code>json_schema</code> qu&#39;après sa propre recette.</td></tr></tbody></table><h2 id="ouvertes--produit-et-arbitrages-différés" tabindex="-1">Ouvertes — produit et arbitrages différés <a class="header-anchor" href="#ouvertes--produit-et-arbitrages-différés" aria-label="Permalink to &quot;Ouvertes — produit et arbitrages différés {#ouvertes--produit-et-arbitrages-différés}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ADR</th><th>Action</th></tr></thead><tbody><tr><td>0001</td><td>Documenter la stratégie de licence d&#39;une éventuelle édition Enterprise.</td></tr><tr><td>0005</td><td>Revoir le positionnement une fois un premier retour marché disponible (aucune échéance).</td></tr><tr><td>0012</td><td>Traiter tout changement des paramètres de fragmentation comme une réindexation.</td></tr><tr><td>0014</td><td>Trancher la déclinaison par locale de <code>content_types.schema</code> et de <code>form_config</code>. (<code>settings.seo</code>, lui, est tranché par l&#39;ADR-0025 : pas de déclinaison.)</td></tr><tr><td>0016</td><td>Mesurer le coût du chargement du vocabulaire sous charge avant d&#39;introduire un cache.</td></tr><tr><td>0020</td><td>Assembler les mentions légales depuis le registre d&#39;attributions.</td></tr><tr><td>0020</td><td>Décider si les attributions se calculent par site plutôt que par organisation (E10 est livré).</td></tr><tr><td>0023</td><td>Réévaluer l&#39;inclusion de l&#39;admin Nuxt dans le paquet, une fois un build de production disponible.</td></tr><tr><td>0028</td><td>Décider si une boutique complète (panier, paiement, stock) devient un Epic de Core ou reste hors produit.</td></tr><tr><td>0037</td><td>Évaluer BGE-M3 sur un corpus réel de collectivité avant de le déclarer <code>validated</code>.</td></tr><tr><td>0043</td><td>Vectoriser les documents extraits nativement pour la recherche sémantique du back-office (RAG).</td></tr><tr><td>0044</td><td>Indexer les transcriptions des sons et des vidéos dans la recherche du site, comme le texte des documents.</td></tr><tr><td>0066</td><td>Indicateur de fraîcheur des traductions de pages, sur le modèle de celui des contenus.</td></tr><tr><td>0046</td><td>Profil « Produit logiciel » (pack Développeurs), après le deuxième jalon.</td></tr><tr><td>0048</td><td>Domaine propre au projet, acheté par le Product Owner (site en ligne sur GitHub Pages depuis le 08/10, axe en CI).</td></tr><tr><td>0067</td><td>Audit manuel d&#39;accessibilité du site, déclaration d&#39;accessibilité et moyen de signaler un défaut.</td></tr><tr><td>0049</td><td>Trancher les déclinaisons d&#39;images par largeur (rouvre « pas de miniatures », ADR-0041) avant le socle du front.</td></tr><tr><td>0049</td><td>Mode sombre du site public : sa condition (« après les quatre thèmes de l&#39;ADR-0047 ») est remplie depuis le 16/10/2026, les quatre thèmes étant livrés (<code>56512a0</code>, v0.11.0 ; <code>apps/front/themes/</code>). À arbitrer par le Product Owner.</td></tr><tr><td>0068</td><td>Faire valider par un juriste la lecture de la FAQ de l&#39;OFL retenue pour les polices à nom réservé.</td></tr><tr><td>0070</td><td>Recette contre un vrai fournisseur S3 (Scaleway, OVH, Backblaze…) et un vrai stockage SFTP, sur un serveur jetable : la CI n&#39;a exercé que MinIO et OpenSSH locaux.</td></tr><tr><td>0070</td><td>Remplacer le MinIO d&#39;essai par une image maintenue et épinglée quand MinIO en republiera une (ou par un autre serveur S3 d&#39;essai).</td></tr><tr><td>0070</td><td>Évaluer l&#39;envoi de données non compressées (déduplication réelle, dépôt plus léger) : changerait le format des sauvegardes locales (ADR-0052).</td></tr><tr><td>0071, 0072</td><td>Ajouter l&#39;anglais à toutes les familles de libellés (Core et extensions livrées), servi par <code>GET /api/v1/i18n/labels?lang=en</code>. Même action dans les deux ADR : la case de l&#39;ADR-0071 renvoie à celle de l&#39;ADR-0072, et les deux restent ouvertes tant que l&#39;anglais n&#39;est pas livré.</td></tr><tr><td>0071</td><td>Acheminer la langue de l&#39;agent connecté jusqu&#39;aux libellés de rôle et aux règles d&#39;accès de page.</td></tr><tr><td>0073</td><td>Appliquer côté serveur la longueur maximale des textes courts (<code>TextFieldDef.max_length</code>, déclarée mais non contrôlée), en ménageant les enregistrements existants plus longs.</td></tr><tr><td>0073</td><td>Rendre les enquêtes dans le front public (saisie question par question, questions obligatoires annoncées) ; le serveur refuse déjà une réponse incomplète.</td></tr></tbody></table><h2 id="ouverte--de-processus-non-vérifiable-après-coup" tabindex="-1">Ouverte — de processus, non vérifiable après coup <a class="header-anchor" href="#ouverte--de-processus-non-vérifiable-après-coup" aria-label="Permalink to &quot;Ouverte — de processus, non vérifiable après coup {#ouverte--de-processus-non-vérifiable-après-coup}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ADR</th><th>Action</th></tr></thead><tbody><tr><td>0002</td><td>Vérifier que chaque bloc développé respecte la frontière Core/plugin avant merge. Le contrôle n&#39;est tracé nulle part ; à transformer en règle de revue, ou à clore comme non tenu.</td></tr></tbody></table><h2 id="conditionnelles--rien-à-programmer" tabindex="-1">Conditionnelles — rien à programmer <a class="header-anchor" href="#conditionnelles--rien-à-programmer" aria-label="Permalink to &quot;Conditionnelles — rien à programmer {#conditionnelles--rien-à-programmer}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ADR</th><th>Déclencheur</th></tr></thead><tbody><tr><td>0016</td><td>Bascule vers OpenSearch (hors périmètre V1.1).</td></tr><tr><td>0021</td><td>Ouverture d&#39;un module de gestion de taxonomie — remplacerait l&#39;ADR.</td></tr><tr><td>0028</td><td>Rouvrir la question d&#39;un mécanisme de dépendance entre plugins si la gêne devient quotidienne.</td></tr><tr><td>0029</td><td>Documenter la liste d&#39;hôtes avec la médiathèque, le jour où une référence média pointera ailleurs. Le lot 1 (ADR-0041) ne sert que le stockage du déploiement : le déclencheur n&#39;est pas survenu.</td></tr><tr><td>0029</td><td>Rouvrir la question d&#39;IPv6 si un déploiement le demande.</td></tr><tr><td>0030</td><td>Rouvrir le sort final « supprimer » si un organisme privé le demande.</td></tr><tr><td>0047</td><td>Epic « menus », si un thème du front de démarrage bute sur l&#39;arbre des pages.</td></tr><tr><td>0056</td><td>Retirer la consigne de format JSON d&#39;une fonction, une fois la garantie constatée pour chaque entrée déclarée <code>json_schema</code> (par <code>ResponseSchema.fallback_instruction</code>).</td></tr><tr><td>0056</td><td>Garantie de forme demandée pour un serveur <code>openai_compatible</code> (vLLM, llama.cpp, Mistral) : une ADR par mécanisme.</td></tr><tr><td>0056</td><td>Lignes étiquetées (SEO, traduction, classification SVE) qui perdent des champs à la recette : rouvrir par une ADR.</td></tr></tbody></table><hr><h2 id="ce-quil-faudrait-changer-dans-la-convention" tabindex="-1">Ce qu&#39;il faudrait changer dans la convention <a class="header-anchor" href="#ce-quil-faudrait-changer-dans-la-convention" aria-label="Permalink to &quot;Ce qu&#39;il faudrait changer dans la convention {#ce-quil-faudrait-changer-dans-la-convention}&quot;">​</a></h2><p>La convention du <a href="/teuthis-cms-distribution/developpeurs/adr/"><code>README</code></a> prévoit quatre statuts (<code>Proposé</code>, <code>Accepté</code>, <code>Accepté avec garde-fou</code>, <code>Remplacé par ADR-NNNN</code>) et interdit d&#39;éditer une ADR après acceptation <strong>pour changer sa décision</strong>. Elle ne dit rien de deux pratiques déjà en usage :</p><ul><li><strong>l&#39;amendement</strong> : l&#39;ADR-0015 porte « Accepté avec garde-fou — amendée par l&#39;ADR-0027 », un statut qui n&#39;est pas dans la liste ;</li><li><strong>la mise à jour</strong> : les ADR-0006 et 0007 ont reçu des sections « Mise à jour » postérieures à leur acceptation.</li></ul><p>Aucune des deux ne change une décision, donc l&#39;esprit de la règle est respecté. Il manque seulement de l&#39;écrire : ajouter le statut <code>Amendée par ADR-NNNN</code>, et autoriser explicitement une section « Mise à jour » datée, à condition qu&#39;elle prolonge la décision sans la contredire.</p><p><strong>Et une règle de tenue : toute ADR ou tout commit qui clôt l&#39;action d&#39;une autre ADR coche sa case, avec sa preuve.</strong> C&#39;est ce qui a manqué au moins huit fois entre le 14 et le 18 septembre, y compris dans des commits récents.</p><p><strong>Fait le 28/09 (audit du 26/09, SUIVI-10)</strong> : la section « Convention » du <a href="/teuthis-cms-distribution/developpeurs/adr/"><code>README</code></a> porte désormais le statut <code>Amendée par ADR-NNNN</code>, les renvois en en-tête (<code>**Amende :**</code> et <code>**Renvois ultérieurs :**</code>), la section « Mise à jour » datée et la règle de tenue.</p><hr><h2 id="historique" tabindex="-1">Historique <a class="header-anchor" href="#historique" aria-label="Permalink to &quot;Historique {#historique}&quot;">​</a></h2><p>Les états successifs du recensement, du plus ancien au plus récent. Les chiffres sont ceux de l&#39;époque : seul l&#39;« État actuel », en tête, fait foi.</p><h3 id="mises-à-jour-du-document" tabindex="-1">Mises à jour du document <a class="header-anchor" href="#mises-à-jour-du-document" aria-label="Permalink to &quot;Mises à jour du document {#mises-à-jour-du-document}&quot;">​</a></h3><p>Revue du 18 septembre 2026, puis mises à jour :</p><ul><li>le 19/09 (ADR-0036, 0037 et 0038) ;</li><li>le 23/09 (ADR-0039 à 0044) ;</li><li>le 24/09 (ADR-0045 à 0049) ;</li><li>le 25/09 (thème de site dans le Core, ADR-0049 ; pile <code>deploy/</code> et installateur, ADR-0045) ;</li><li>le 26/09 (audit complet : quatre cases rétro-cochées ; ADR-0050 à 0053) ;</li><li>le 27/09 (ADR-0054 et 0055 ; ADR-0056, alors proposée, acceptée depuis le 29/09 à périmètre réduit) ;</li><li>le 28/09 (lot 5 de l&#39;audit du 26/09 : ADR-0057 à 0060, SUIVI-1 à 4, 11 et 12 ; lot 6 du même audit : SUIVI-5 à 10, 13 et 14) ;</li><li>le 21/10 (ADR-0074, constat SEC-8) ;</li><li>le 04/11 (lot 6 de l&#39;audit du 21/10 : tenue documentaire, SUIVI-15 à 29) ;</li><li>le 04/11 (lot 2 de l&#39;audit du 21/10 : chaîne de distribution, EXP-19 à 25 ; ADR-0075 et 0076, quatre cases ouvertes et cinq cochées à leur création) ;</li><li>le 05/11 (répétition à blanc verte et environnement <code>distribution</code> créé : deux cases des ADR-0075 et 0076 cochées).</li></ul><p>À la date du 28/09, l&#39;en-tête annonçait pour périmètre « les cases non cochées des 56 ADR de <code>docs/adr/</code> ».</p><h3 id="1809--la-revue" tabindex="-1">18/09 — la revue <a class="header-anchor" href="#1809--la-revue" aria-label="Permalink to &quot;18/09 — la revue {#1809--la-revue}&quot;">​</a></h3><p>Au début de la revue, on comptait 54 cases ouvertes sur 33 ADR, puis 58 sur 35 ADR avant correction.</p><h3 id="1909--adr-0036-à-0038" tabindex="-1">19/09 — ADR-0036 à 0038 <a class="header-anchor" href="#1909--adr-0036-à-0038" aria-label="Permalink to &quot;19/09 — ADR-0036 à 0038 {#1909--adr-0036-à-0038}&quot;">​</a></h3><p>Les deux contradictions sont closes, et les ADR-0036 et 0037 apportent chacun une action.</p><p>L&#39;ADR-0038 clôt la seule action bloquante (ADR-0017), coche ses deux actions livrées et en ouvre deux.</p><h3 id="2309--adr-0039-à-0044" tabindex="-1">23/09 — ADR-0039 à 0044 <a class="header-anchor" href="#2309--adr-0039-à-0044" aria-label="Permalink to &quot;23/09 — ADR-0039 à 0044 {#2309--adr-0039-à-0044}&quot;">​</a></h3><ul><li>ADR-0039 (journalisation applicative, constat P1 n°6) : coche son action livrée et en ouvre deux — envoi vers un agrégateur externe, rotation et conservation des journaux du conteneur — toutes deux laissées à l&#39;exploitant.</li><li>ADR-0040 (échangeur OIDC des usagers, constat P1 n°5) : coche son action livrée et en ouvre trois — recette contre l&#39;intégration FranceConnect réelle, déconnexion fédérée, contrôle de la revendication <code>acr</code>.</li><li>ADR-0041 (médiathèque, lot 1, constat P1 n°4) : clôt l&#39;action « médiathèque » de l&#39;ADR-0017, coche ses deux actions livrées — socle API et écran du back-office — et en ouvre quatre — lot 2, vérification de <code>pages.image_id</code>, octets des médias à la suppression d&#39;une organisation, vidéo.</li><li>ADR-0042 (médiathèque, lot 2, constat SEO S12) : coche le lot 2 et la vérification de <code>pages.image_id</code> de l&#39;ADR-0041, coche ses deux actions livrées et en ouvre deux — extraction documentaire, reportée hors du lot 2, et recette dans un navigateur.</li><li>ADR-0043 (extraction documentaire native et Apache Tika livré inactif) : coche l&#39;extraction de l&#39;ADR-0042, coche ses deux actions livrées et en ouvre deux — date des documents dans l&#39;index, vectorisation pour la recherche sémantique.</li><li>ADR-0044 (vidéo, dépôt en flux, sous-titres et transcription) : coche l&#39;action conditionnelle « vidéo » de l&#39;ADR-0041, coche ses deux actions livrées et en ouvre deux — recette contre le démon ClamAV réel avec une grosse vidéo, indexation des transcriptions.</li></ul><h3 id="2409--plan-de-déploiement-par-usage" tabindex="-1">24/09 — plan de déploiement par usage <a class="header-anchor" href="#2409--plan-de-déploiement-par-usage" aria-label="Permalink to &quot;24/09 — plan de déploiement par usage {#2409--plan-de-déploiement-par-usage}&quot;">​</a></h3><p>Les ADR-0045 à 0048 n&#39;en cochent aucune et en ouvrent dix-neuf : six pour le déploiement (images, publication GHCR, pile de production, installateur, commande <code>teuthis</code>, copie distante des sauvegardes), trois pour les profils d&#39;usage, sept pour le front de démarrage (socle, quatre thèmes, recette réelle, et l&#39;Epic « menus » conditionnel) et trois pour le site du projet.</p><p>Le même jour, les images de production et la commande <code>provision</code> cochent la première action de l&#39;ADR-0045 et l&#39;action de l&#39;ADR-0026 sur les organisations provisionnées par d&#39;autres voies ; le mécanisme des profils et les cinq profils livrés cochent les deux premières actions de l&#39;ADR-0046.</p><p>L&#39;ADR-0049 (identité visuelle du site public) en ouvre sept : thème de site dans le Core, écran « Apparence », liste des polices, règles d&#39;affichage adaptatif, thème par défaut de chaque profil, déclinaisons d&#39;images par largeur, et le mode sombre conditionnel.</p><h3 id="2509--thème-de-site-pile-deploy-installateur" tabindex="-1">25/09 — thème de site, pile <code>deploy/</code>, installateur <a class="header-anchor" href="#2509--thème-de-site-pile-deploy-installateur" aria-label="Permalink to &quot;25/09 — thème de site, pile `deploy/`, installateur {#2509--thème-de-site-pile-deploy-installateur}&quot;">​</a></h3><p>Le thème de site dans le Core coche la première action de l&#39;ADR-0049.</p><p>Le workflow de publication GHCR est livré, mais l&#39;action de l&#39;ADR-0045 reste ouverte jusqu&#39;à la première release et aux paquets rendus publics.</p><p>La pile de production <code>deploy/</code> coche la troisième action de l&#39;ADR-0045 ; sa rotation des journaux (10 Mo × 5 par conteneur) couvre en partie l&#39;action de l&#39;ADR-0039, dont la durée de conservation reste à décider.</p><p>L&#39;installateur shell coche la quatrième action de l&#39;ADR-0045.</p><h3 id="2609--audit-complet-adr-0050-à-0053" tabindex="-1">26/09 — audit complet, ADR-0050 à 0053 <a class="header-anchor" href="#2609--audit-complet-adr-0050-à-0053" aria-label="Permalink to &quot;26/09 — audit complet, ADR-0050 à 0053 {#2609--audit-complet-adr-0050-à-0053}&quot;">​</a></h3><p>L&#39;audit du 26/09 a trouvé quatre actions livrées depuis août mais jamais cochées (ADR-0014, 0019, 0021, 0022) : elles sont cochées avec leur preuve, et listées dans « Closes pendant l&#39;audit du 26/09 ».</p><p>L&#39;ADR-0050 (verrou « clé attendue », constat SEC-1) n&#39;ouvre aucune action et coche celle qu&#39;elle livre ; l&#39;ADR-0051 (conservation du texte des échanges avec l&#39;IA, constat RGPD-3) et l&#39;ADR-0052 (sauvegarde nocturne, constat EXP-1) font de même.</p><p>L&#39;ADR-0053 (écritures anonymes sous <code>/api/v1/public/</code>, constat SEC-2) coche l&#39;action qu&#39;elle livre et en ouvre une : retirer les alias dépréciés.</p><h3 id="2709--adr-0054-0055-et-0056" tabindex="-1">27/09 — ADR-0054, 0055 et 0056 <a class="header-anchor" href="#2709--adr-0054-0055-et-0056" aria-label="Permalink to &quot;27/09 — ADR-0054, 0055 et 0056 {#2709--adr-0054-0055-et-0056}&quot;">​</a></h3><p>L&#39;ADR-0054 (métadonnées des images retirées au dépôt, constat RGPD-4) coche l&#39;action qu&#39;elle livre et en ouvre une : nettoyer les images déjà déposées.</p><p>L&#39;ADR-0055 (lecture publique d&#39;une fiche publiée non journalisée, constat RGPD-12) n&#39;ouvre aucune action.</p><p>L&#39;ADR-0056 (sortie structurée par schéma), alors au statut <code>Proposé</code>, en ouvrait dix : sept à programmer si elle était acceptée, et trois conditionnelles. Elle est acceptée depuis le 29/09, à périmètre réduit : il ne lui reste que quatre cases ouvertes, la recette contre OpenAI, Anthropic et Gemini et trois conditionnelles (voir son statut et sa « Décision du 29 septembre »).</p><h3 id="2809--lots-5-et-6-de-laudit-du-2609" tabindex="-1">28/09 — lots 5 et 6 de l&#39;audit du 26/09 <a class="header-anchor" href="#2809--lots-5-et-6-de-laudit-du-2609" aria-label="Permalink to &quot;28/09 — lots 5 et 6 de l&#39;audit du 26/09 {#2809--lots-5-et-6-de-laudit-du-2609}&quot;">​</a></h3><p>Le lot 5 verse quatre ADR : 0057 (authenticité des images, EXP-10) en ouvre une, la première publication réelle ; 0058 (clôture d&#39;une organisation, RGPD-7) et 0060 (balayage des orphelins, son filet) n&#39;en laissent aucune ouverte ; 0059 (droits des abonnés, RGPD-8) en ouvre deux, côté site public.</p><p>Le même lot (SUIVI-1 à 4) a vérifié dans le code les quatre cases rétro-cochées des ADR-0014, 0019, 0021 et 0022, et précisé leurs preuves (fichier et lignes) ; aucune ne figure plus parmi les ouvertes, d&#39;où des nombres inchangés.</p><p>Le même lot (SUIVI-11 et 12) a rendu à l&#39;ADR-0015 sa décision n°1 telle qu&#39;acceptée, renvoyant à l&#39;ADR-0027 qui l&#39;amende, et ajouté en tête des ADR amendées ou prolongées un renvoi vers l&#39;ADR ultérieure, sans toucher aux décisions ni aux cases.</p><p>Le lot 6 coche l&#39;écran des dictionnaires de l&#39;ADR-0016 (SUIVI-5 : le Product Owner a jugé que synonymes et mots vides l&#39;un sous l&#39;autre sur le même écran suffisent), note comme partiel l&#39;écran « Apparence » de l&#39;ADR-0049 sans le cocher (SUIVI-6 : relais du BFF présents, page absente) et corrige le texte d&#39;une case déjà cochée de l&#39;ADR-0004 (SUIVI-7) : d&#39;où une case ouverte de moins.</p><p>S14 et S17 de l&#39;audit du 26/09 ont coché une case de l&#39;ADR-0035 et une de l&#39;ADR-0034.</p><p>Décompte de l&#39;époque, par <code>grep -o &quot;\\- \\[ \\]&quot;</code> sur toutes les ADR de <code>docs/adr/</code> : 71 cases ouvertes avant l&#39;ADR-0056 et 81 après, soit les dix cases de l&#39;ADR-0056 alors proposée. Ces deux nombres précèdent son acceptation à périmètre réduit du 29/09 et ne sont pas comparables aux états suivants.</p><h3 id="0110--63-ouvertes-147-cochées" tabindex="-1">01/10 — 63 ouvertes, 147 cochées <a class="header-anchor" href="#0110--63-ouvertes-147-cochées" aria-label="Permalink to &quot;01/10 — 63 ouvertes, 147 cochées {#0110--63-ouvertes-147-cochées}&quot;">​</a></h3><p><strong>État au 01/10 : 63 cases ouvertes, 147 cochées, aucune bloquante.</strong></p><h3 id="0910--complément-à-ladr-0059" tabindex="-1">09/10 — complément à l&#39;ADR-0059 <a class="header-anchor" href="#0910--complément-à-ladr-0059" aria-label="Permalink to &quot;09/10 — complément à l&#39;ADR-0059 {#0910--complément-à-ladr-0059}&quot;">​</a></h3><p>Le complément du 09/10 à l&#39;ADR-0059 (issue #15 : canaux actifs et durée du lien dans le descripteur public, désinscription complète de la lettre) ajoute une case cochée, avec sa preuve, et n&#39;en ouvre aucune.</p><h3 id="1810--avant-ladr-0074" tabindex="-1">18/10 — avant l&#39;ADR-0074 <a class="header-anchor" href="#1810--avant-ladr-0074" aria-label="Permalink to &quot;18/10 — avant l&#39;ADR-0074 {#1810--avant-ladr-0074}&quot;">​</a></h3><p>État au 18/10, avant l&#39;ADR-0074 : 54 cases ouvertes, 201 cochées.</p><h3 id="2110--adr-0074-sec-8" tabindex="-1">21/10 — ADR-0074 (SEC-8) <a class="header-anchor" href="#2110--adr-0074-sec-8" aria-label="Permalink to &quot;21/10 — ADR-0074 (SEC-8) {#2110--adr-0074-sec-8}&quot;">​</a></h3><p><strong>État au 21/10 : 57 cases ouvertes, 204 cochées, aucune bloquante</strong>, sur les ADR-0001 à 0074.</p><p>L&#39;ADR-0074 (adresse d&#39;un compte fédéré, constat SEC-8 de l&#39;audit du 21/10, issue #37) coche trois actions livrées (réglage et règle de rétention, case de l&#39;admin, notice) et en ouvre trois, listées dans « Ouvertes — sécurité et exploitation » : le traitement des comptes fédérés déjà créés, la vérification de ce que FranceConnect rend dans <code>email_verified</code>, et le même défaut sur le numéro de téléphone.</p><h3 id="0411--lot-6-de-laudit-du-2110-tenue-documentaire" tabindex="-1">04/11 — lot 6 de l&#39;audit du 21/10 (tenue documentaire) <a class="header-anchor" href="#0411--lot-6-de-laudit-du-2110-tenue-documentaire" aria-label="Permalink to &quot;04/11 — lot 6 de l&#39;audit du 21/10 (tenue documentaire) {#0411--lot-6-de-laudit-du-2110-tenue-documentaire}&quot;">​</a></h3><p>L&#39;ADR-0006 coche « Installer la GitHub App Renovate » (SUIVI-16) : une case ouverte de moins, une cochée de plus, soit 56 ouvertes et 205 cochées.</p><p>L&#39;ADR-0056, acceptée depuis le 29/09, n&#39;est plus classée « ADR proposée » : sa recette reste parmi les ouvertes, ses trois conditionnelles dans « Conditionnelles » (SUIVI-15).</p><p>Les deux actions « Ajouter l&#39;anglais » (ADR-0071 et 0072) ne forment plus qu&#39;une ligne (SUIVI-23), et le mode sombre de l&#39;ADR-0049, dont la condition est remplie, passe aux arbitrages du Product Owner (SUIVI-24).</p>',96)])])}const h=t(s,[["render",o]]);export{m as __pageData,h as default};
